    video_id uuid,
    relay_path text NOT NULL,
    analytics jsonb DEFAULT '{"face": false, "zones": false, "fire_exit": false, "fire_smoke": false, "people_count": false}'::jsonb NOT NULL,
    analytics_fps smallint DEFAULT 5 NOT NULL,
    resolution text,
    worker_id text,
