    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    status jsonb,
    search_tags text[],
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    is_running boolean DEFAULT false NOT NULL,
    CONSTRAINT camera_analytics_fps_check CHECK (((analytics_fps >= 1) AND (analytics_fps <= 30))),
    CONSTRAINT camera_source_type_check CHECK ((source_type = ANY (ARRAY['rtsp'::text, 'file'::text]))),
    CONSTRAINT ck_camera_source CHECK ((((source_type = 'rtsp'::text) AND (main_stream_url IS NOT NULL) AND (video_id IS NULL)) OR ((source_type = 'file'::text) AND (video_id IS NOT NULL) AND (main_stream_url IS NULL) AND (sub_stream_url IS NULL))))
);


